24	namespace ulysses {
25	
26	namespace {
27	
28	// Before any CUDAGuard: constructing one from a CPU tensor aborts inside c10 with a message that
29	// names neither this library nor the argument. docs/api.md promises this wording.
30	void require_cuda(const at::Tensor& input)
31	{
32	    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor, got one on ", input.device());
33	}
34	
35	// The windows live on one device and the barrier kernel dereferences their flag pointers, so a
36	// tensor from another device would launch that kernel on the wrong one. Per-tensor, so it stays out
37	// of the plan cache key.
38	void require_group_device(const UlyssesGroup& group, const at::Tensor& input)
39	{
40	    // static_cast: c10::DeviceIndex is int8_t, so streaming it prints a CHARACTER. Device 0 is a
41	    // NUL, which truncates the rest of the message.
42	    TORCH_CHECK(input.device().index() == group.device_index(),
43	                "input is on cuda:",
44	                static_cast<int64_t>(input.device().index()),
45	                " but this UlyssesGroup was built for cuda:",
46	                group.device_index(),
47	                "; one group serves exactly one device");
48	}
49	
50	// vmap has no batching rule for these ops, so it falls back to a for-loop and turns one call into
51	// one per batch element -- silently. For a collective that is the failure this library documents
52	// most loudly: ranks whose batch sizes differ then issue different NUMBERS of collectives and
53	// hang, with nothing raised and nothing timed out. The loop is also wrong for the ops that
54	// allocate, since each iteration would rendezvous.
55	//
56	// One boxed kernel serves every op in the table; it only ever throws. Boxed because
57	// torch::CppFunction has no makeError().
58	void refuse_vmap(const c10::OperatorHandle& op, c10::Stack*)
59	{
60	    TORCH_CHECK(false,
61	                op.schema().operator_name().name,
62	                " does not support torch.vmap: it is a collective, and vmap would run it once "
63	                "per batch element -- ranks that disagree on the batch size would then hang. "
64	                "Call it once, outside vmap, on the full tensor. Reached from "
65	                "torch.autograd.grad(is_grads_batched=True) too, which batches the backward "
66	                "through the same for-loop.");
67	}
68	
69	// Byte intervals [a, a+a_bytes) and [b, b+b_bytes) intersect.
70	bool intervals_overlap(const void* a, int64_t a_bytes, const void* b, int64_t b_bytes)
71	{
72	    const auto* pa = static_cast<const char*>(a);
73	    const auto* pb = static_cast<const char*>(b);
74	    return pa < pb + b_bytes && pb < pa + a_bytes;
75	}
76	
77	// The validated input, the destination, the window the transfer fills, and whether those last two
78	// are the same buffer.
79	struct Call {
80	    at::Tensor     x;
81	    at::Tensor     output;
82	    const A2APlan* plan          = nullptr;
83	    const Window*  win           = nullptr;
84	    bool           out_is_window = false;
85	};
86	
87	// Everything here runs BEFORE the call's first barrier, so a rejected argument leaves no rank
88	// waiting on peers that did not reject it.
89	Call prepare(const c10::intrusive_ptr<UlyssesGroup>&    group,
90	             const at::Tensor&                          input,
91	             int64_t                                    mode,
92	             const std::optional<std::vector<int64_t>>& seq_splits,
93	             const std::optional<std::vector<int64_t>>& head_splits,
94	             const std::optional<at::Tensor>&           out,
95	             WindowRole                                 role,
96	             bool                                       lend)
97	{
98	    Call call;
99	    // Here rather than deeper in: window() and make_output() also check, but the zero-copy path
100	    // reaches neither, and by the time anything else would notice the opening barrier has already
101	    // been issued -- so the rank that noticed would be waiting on peers instead of throwing.
102	    group->check_alive();
103	    // Released buffers go back to the allocator here, before this call takes any Window& out of
104	    // owned_. make_output() is the only other place that can prune, so a caller who takes one
105	    // buffer from empty_output() and drops it would otherwise pin it until destroy().
106	    group->prune_owned();
107	    require_cuda(input);
108	    require_group_device(*group, input);
109	    call.x    = input.contiguous();
110	    call.plan = &group->plan(call.x.sizes(), mode, call.x.scalar_type(), seq_splits, head_splits);
111	
112	    if (out.has_value()) {
113	        call.output = *out;
114	        TORCH_CHECK(call.output.is_cuda() && call.output.is_contiguous(), "out must be a contiguous CUDA tensor");
115	        TORCH_CHECK(call.output.device().index() == group->device_index(),
116	                    "out is on cuda:",
117	                    static_cast<int64_t>(call.output.device().index()),
118	                    " but this UlyssesGroup was built for cuda:",
119	                    group->device_index());
120	        TORCH_CHECK(call.output.scalar_type() == call.x.scalar_type(),
121	                    "out has dtype ",
122	                    call.output.scalar_type(),
123	                    ", expected ",
124	                    call.x.scalar_type());
125	        TORCH_CHECK(call.output.sizes() == at::IntArrayRef(call.plan->output_shape),
126	                    "out has shape ",
127	                    call.output.sizes(),
128	                    ", expected ",
129	                    at::IntArrayRef(call.plan->output_shape));
130	        // A buffer from empty_output() IS a window, and the peers write it directly. Compared in
131	        // BYTES: a window is found by address, so the dtype it was allocated for need not be this
132	        // call's, and comparing the two element counts would admit a buffer too small to hold what
133	        // the peers are about to write into it.
134	        const Window* owned = group->window_of(call.output);
135	        if (owned != nullptr && owned->tensor.nbytes() >= call.plan->window_numel * call.x.element_size()) {
136	            call.win           = owned;
137	            call.out_is_window = true;
138	        }
139	    }
140	    else if (lend) {
141	        // No `out`, but the caller accepts a lent window: the peers write it directly and the
142	        // result IS that window, so there is no copy-out and the caller owns no buffer. Which
143	        // window is a rotation the group drives, not a choice this call makes -- see lend_window().
144	        const Window& lent = group->lend_window(call.x.scalar_type(), call.plan->window_numel);
145	        call.win           = &lent;
146	        call.out_is_window = true;
147	        call.output =
148	            lent.tensor.narrow(0, 0, c10::multiply_integers(call.plan->output_shape)).view(call.plan->output_shape);
149	    }
150	    else {
151	        call.output = at::empty(call.plan->output_shape, call.x.options());
152	    }
153	
154	    if (call.win == nullptr) {
155	        call.win = &group->window(role, call.x.scalar_type(), call.plan->window_numel);
156	    }
157	
158	    // Refuse a call whose input, or whose `out`, shares bytes with the window it is about to fill
159	    // -- it would be read while every peer writes it. `out` BEING the window is the zero-copy path
160	    // and the one legitimate case. Intervals, not a pointer comparison, because an overlap can
161	    // start past the window's base. The window's OWN byte size, for the reason above.
162	    const void*   base  = reinterpret_cast<const void*>(call.win->peer_ptrs[group->rank()]);
163	    const int64_t bytes = call.win->tensor.nbytes();
164	    TORCH_CHECK(!intervals_overlap(call.x.data_ptr(), call.x.nbytes(), base, bytes),
165	                "input overlaps the window this call fills: it would be read while every peer "
166	                "writes it. Pass a separate output buffer, or let the call allocate one.");
167	    if (!call.out_is_window) {
168	        TORCH_CHECK(!intervals_overlap(call.output.data_ptr(), call.output.nbytes(), base, bytes),
169	                    "out overlaps the window this call fills without being it, which neither "
170	                    "writes correctly nor copies out correctly. Pass a whole buffer from "
171	                    "group.empty_output(), or one outside symmetric memory.");
172	    }
173	    return call;
174	}
175	
176	// Records the staging release on scope exit, INCLUDING when the transfer throws. Without it a
177	// throw after the copies were issued leaves the release event unrecorded, and the next call for
178	// that shape overwrites the staging buffer while the comm stream is still reading it -- silently,
179	// because waiting on an unrecorded event succeeds and does nothing.
180	struct StagingRelease {
181	    UlyssesGroup*          group;
182	    UlyssesGroup::Staging* slot;
183	    cudaStream_t           comm;
184	
185	    ~StagingRelease()
186	    {
187	        // The slot this call used, not "the last one staged": several calls of one shape can be in
188	        // flight, and each has to release its own.
189	        group->release_staging(slot, comm);  // noexcept; see the header
190	    }
191	};
192	
193	// Barrier, transfer, barrier: everything the call does to the window, ordered on `stream`.
194	void transfer_on_stream(const c10::intrusive_ptr<UlyssesGroup>& group, const Call& call, cudaStream_t stream)
195	{
196	    const int rank = static_cast<int>(group->rank());
197	
198	    // WRITERS WAIT FOR READERS, before writing anything. The window is single-buffered, so this
199	    // call is about to overwrite what the previous one produced, which a peer may still be
200	    // reading; the closing barrier below proves everyone's WRITES landed and nothing about their
201	    // READS. It guards the START of a call rather than the end of the previous one because on the
202	    // zero-copy path the result is read by the caller at a time the operator never sees.
203	    fast_barrier(stream, call.win->flag_ptrs, rank);
204	
205	    launch_a2a_ce(call.x.data_ptr(), call.win->peer_ptrs, *call.plan, group->xfer_stream(), rank, stream);
206	
207	    // That a completed peer memcpy is VISIBLE at the destination when this kernel's release store
208	    // arrives is an ASSUMPTION, not a documented guarantee -- test/distributed/ce_ordering.py is
209	    // the negative control for it.
210	    fast_barrier(stream, call.win->flag_ptrs, rank);
211	}
212	
213	// Window -> the caller's tensor, ordered after the closing barrier on the same stream. Every
214	// rank's result is dense from the window base, so this is one flat device-to-device copy -- this
215	// rank's own share included, since it travels through the window like every peer's.
216	void copy_out(const Call& call, cudaStream_t stream, int rank)
217	{
218	    ULYSSES_CUDA_CHECK(cudaMemcpyAsync(call.output.data_ptr(),
219	                                       reinterpret_cast<const void*>(call.win->peer_ptrs[rank]),
220	                                       static_cast<size_t>(call.output.nbytes()),
221	                                       cudaMemcpyDeviceToDevice,
222	                                       stream));
223	}
224	
225	at::Tensor run(const c10::intrusive_ptr<UlyssesGroup>&    group,
226	               const at::Tensor&                          input,
227	               int64_t                                    mode,
228	               const std::optional<std::vector<int64_t>>& seq_splits,
229	               const std::optional<std::vector<int64_t>>& head_splits,
230	               const std::optional<at::Tensor>&           out,
231	               WindowRole                                 role,
232	               cudaStream_t                               stream,
233	               bool                                       lend)
234	{
235	    const Call call = prepare(group, input, mode, seq_splits, head_splits, out, role, lend);
236	    transfer_on_stream(group, call, stream);
237	    if (!call.out_is_window) {
238	        copy_out(call, stream, static_cast<int>(group->rank()));
239	    }
240	    return call.output;
241	}
242	
243	}  // namespace
244	
245	// The one collective, in two forms.
246	//
247	// They are two ops rather than one with an optional `out` because a single op cannot be both
248	// honest and differentiable. Declaring the alias `out` really has -- Tensor(a!) -- makes the
249	// schema mutable, and torch/library.py refuses to register an autograd formula for a mutable
250	// operator. Splitting gives the functional form autograd and a meta kernel, and gives the
251	// out-variant an annotation that matches what it does. `-> ()` rather than `-> Tensor(a!)`
252	// because can_auto_functionalize accepts only that shape, so only that shape can enter a graph.
253	at::Tensor all_to_all_4d(const c10::intrusive_ptr<UlyssesGroup>&    group,
254	                         const at::Tensor&                          input,
255	                         int64_t                                    mode,
256	                         const std::optional<std::vector<int64_t>>& seq_splits,
257	                         const std::optional<std::vector<int64_t>>& head_splits)
258	{
259	    require_cuda(input);
260	    const at::cuda::CUDAGuard guard(input.device());
261	    return run(group,
262	               input,
263	               mode,
264	               seq_splits,
265	               head_splits,
266	               std::nullopt,
267	               kSyncWindow,
268	               at::cuda::getCurrentCUDAStream(),
269	               /*lend=*/false);
270	}
271	
272	// Shape propagation for FakeTensor and AOTAutograd. CompositeExplicitAutograd already covers the
273	// Meta key, so without this a fake tensor reaches the real kernel and dies on require_cuda -- a
274	// message about a CUDA tensor, for what is really an untraceable-op problem. A direct Meta
275	// registration takes precedence over the alias.
276	//
277	// The arithmetic stays in group->plan(): it is pure host code that allocates nothing on the device,
278	// so it is safe here, and it runs every shape, dtype and splits check on the way. Rewriting the
279	// uneven-splits rule in Python would put a second copy of it somewhere test_plan.py cannot reach --
280	// which is the whole reason a2a_plan.cc is a torch-free, CUDA-free translation unit.
281	//
282	// The group is a real object on this path: FakeTensorMode's conversion only touches tensors, so the
283	// ScriptObject arrives intact and world_size is available -- which it is not from the input shape
284	// alone when the splits are absent.
285	at::Tensor all_to_all_4d_meta(const c10::intrusive_ptr<UlyssesGroup>&    group,
286	                              const at::Tensor&                          input,
287	                              int64_t                                    mode,
288	                              const std::optional<std::vector<int64_t>>& seq_splits,
289	                              const std::optional<std::vector<int64_t>>& head_splits)
290	{
291	    const A2APlan& plan = group->plan(input.sizes(), mode, input.scalar_type(), seq_splits, head_splits);
292	    return at::empty(plan.output_shape, input.options());
293	}
294	
295	// empty_output is a COLLECTIVE allocation, so it cannot be traced at all: replaying a trace would
296	// put the rendezvous wherever the graph happens to place it rather than where every rank's own
297	// program reaches it. Say that, instead of letting it fall through to a CUDA-tensor complaint.
298	at::Tensor empty_output_meta(const c10::intrusive_ptr<UlyssesGroup>&,
299	                             const at::Tensor&,
300	                             int64_t,
301	                             const std::optional<std::vector<int64_t>>&,
302	                             const std::optional<std::vector<int64_t>>&)
303	{
304	    TORCH_CHECK(false,
305	                "empty_output is a collective allocation and cannot be traced: every rank has to "
306	                "reach it at the same point in its own program. Call it eagerly, outside the "
307	                "region being traced, and pass the buffer in.");
308	}
309	
310	// Fills `out`. A buffer from empty_output() IS the window, so the peers write it directly and the
311	// copy-out disappears; any other contiguous tensor of the output shape is copied into.
312	void all_to_all_4d_out(const c10::intrusive_ptr<UlyssesGroup>&    group,
313	                       const at::Tensor&                          input,
314	                       int64_t                                    mode,
315	                       const std::optional<std::vector<int64_t>>& seq_splits,
316	                       const std::optional<std::vector<int64_t>>& head_splits,
317	                       const at::Tensor&                          out)
318	{
319	    require_cuda(input);
320	    const at::cuda::CUDAGuard guard(input.device());
321	    run(group,
322	        input,
323	        mode,
324	        seq_splits,
325	        head_splits,
326	        out,
327	        kSyncWindow,
328	        at::cuda::getCurrentCUDAStream(),
329	        /*lend=*/false);
330	}
331	
332	// The out-variant's share of the shape rule. Without it a fake tensor reaches the real kernel and
333	// dies on require_cuda -- the misleading message all_to_all_4d_meta exists to prevent -- on the very
334	// variant the schema split was made for, since `-> ()` is the only shape can_auto_functionalize
335	// accepts. Nothing to return: the caller's buffer is the result and its shape is checked, not
336	// derived.
337	void all_to_all_4d_out_meta(const c10::intrusive_ptr<UlyssesGroup>&    group,
338	                            const at::Tensor&                          input,
339	                            int64_t                                    mode,
340	                            const std::optional<std::vector<int64_t>>& seq_splits,
341	                            const std::optional<std::vector<int64_t>>& head_splits,
342	                            const at::Tensor&                          out)
343	{
344	    const A2APlan& plan = group->plan(input.sizes(), mode, input.scalar_type(), seq_splits, head_splits);
345	    TORCH_CHECK(out.scalar_type() == input.scalar_type(),
346	                "out has dtype ",
347	                out.scalar_type(),
348	                ", expected ",
349	                input.scalar_type());
350	    TORCH_CHECK(out.sizes() == at::IntArrayRef(plan.output_shape),
351	                "out has shape ",
352	                out.sizes(),
353	                ", expected ",
354	                at::IntArrayRef(plan.output_shape));
355	}
356	
357	// The async form's device-side half. Python has already made the comm stream current; `caller` is
358	// the stream the user was on, which is where the input is staged.
359	//
360	// Everything both staged forms share, so the split above costs one wrapper rather than a
361	// duplicated body.
362	namespace {
363	
364	at::Tensor run_staged(const c10::intrusive_ptr<UlyssesGroup>&    group,
365	                      const at::Tensor&                          input,
366	                      int64_t                                    mode,
367	                      const std::optional<std::vector<int64_t>>& seq_splits,
368	                      const std::optional<std::vector<int64_t>>& head_splits,
369	                      const std::optional<at::Tensor>&           out,
370	                      int64_t                                    caller_stream_id,
371	                      int64_t                                    caller_device_index,
372	                      bool                                       lend)
373	{
374	    // Both before stage(), unlike every other check, which prepare() runs. destroy() returns early
375	    // the second time, so a staging entry created after it is never freed and its event leaks with
376	    // the group. And the staging buffer takes the INPUT's device while being cached by shape and
377	    // dtype alone, so one wrong-device call would leave a buffer on that device behind and every
378	    // later call for that shape would copy across devices before failing this same check. The comm
379	    // stream below is read through the current device too, which a guard on the wrong one moves.
380	    group->check_alive();
381	    require_cuda(input);
382	    require_group_device(*group, input);
383	    const at::cuda::CUDAGuard guard(input.device());
384	    cudaStream_t              comm = at::cuda::getCurrentCUDAStream();
385	    // Rebuilt from torch's own identifiers rather than wrapped from a raw handle, so the caching
386	    // allocator sees the same stream object the caller was using.
387	    const c10::cuda::CUDAStream caller(c10::Stream::unpack3(
388	        caller_stream_id, static_cast<c10::DeviceIndex>(caller_device_index), c10::DeviceType::CUDA));
389	    // Stage on the caller's stream, so the caller's tensor is never read by the comm stream --
390	    // record_stream would instead pin every freed input until the comm stream caught up. The
391	    // staging copy also absorbs a strided input, which is why nothing calls contiguous() here:
392	    // doing so would launch that copy on the comm stream, which is exactly what this avoids.
393	    UlyssesGroup::Staging* slot = group->stage(input, caller, comm);
394	    const StagingRelease   release{group.get(), slot, comm};
395	    return run(group, slot->tensor, mode, seq_splits, head_splits, out, kAsyncWindow, comm, lend);
396	}
397	
398	}  // namespace
399	
400	at::Tensor all_to_all_4d_staged(const c10::intrusive_ptr<UlyssesGroup>&    group,
401	                                const at::Tensor&                          input,
402	                                int64_t                                    mode,
403	                                const std::optional<std::vector<int64_t>>& seq_splits,
404	                                const std::optional<std::vector<int64_t>>& head_splits,
405	                                int64_t                                    caller_stream_id,
406	                                int64_t                                    caller_device_index,
407	                                bool                                       lend)
408	{
409	    return run_staged(
410	        group, input, mode, seq_splits, head_splits, std::nullopt, caller_stream_id, caller_device_index, lend);
411	}
412	
413	void all_to_all_4d_staged_out(const c10::intrusive_ptr<UlyssesGroup>&    group,
414	                              const at::Tensor&                          input,
415	                              int64_t                                    mode,
416	                              const std::optional<std::vector<int64_t>>& seq_splits,
417	                              const std::optional<std::vector<int64_t>>& head_splits,
418	                              const at::Tensor&                          out,
419	                              int64_t                                    caller_stream_id,
420	                              int64_t                                    caller_device_index)
421	{
422	    run_staged(group, input, mode, seq_splits, head_splits, out, caller_stream_id, caller_device_index, /*lend=*/false);
423	}
424	
425	// The staged pair REFUSES to be traced, the way empty_output does, rather than propagating a
426	// shape it could perfectly well compute.
427	//
428	// Returning a shape here is not half an answer, it is a wrong one, because this op is only ever
429	// reached through all_to_all_4d_async and the Python around it is eager-only. Let the op return
430	// and that wrapper goes on to record a completion event on the comm stream and hand it to torch's
431	// work registry, then call record_stream on the result: a traced call therefore leaves a real
432	// Work in a process-global registry that nothing will ever wait on, and returns an
433	// AsyncCollectiveTensor whose wait() claims a transfer that was never issued. The arguments say
434	// the same thing -- caller_stream_id and caller_device_index name a live CUDA stream, and a graph
435	// that has one baked into it is wrong everywhere it is replayed.
436	//
437	// The shape half is available from all_to_all_4d, which moves exactly the same bytes.
438	at::Tensor all_to_all_4d_staged_meta(const c10::intrusive_ptr<UlyssesGroup>&,
439	                                     const at::Tensor&,
440	                                     int64_t,
441	                                     const std::optional<std::vector<int64_t>>&,
442	                                     const std::optional<std::vector<int64_t>>&,
443	                                     int64_t,
444	                                     int64_t,
445	                                     bool)
446	{
447	    TORCH_CHECK(false,
448	                "all_to_all_4d_async cannot be traced: it completes through a CUDA event bound to "
449	                "torch's work registry and takes the caller's stream as an argument, neither of "
450	                "which a traced call has. Trace all_to_all_4d instead, which moves the same bytes.");
451	}
452	
453	// Same refusal, same reason: the out-variant's completion is registered against `out`.
454	void all_to_all_4d_staged_out_meta(const c10::intrusive_ptr<UlyssesGroup>&,
455	                                   const at::Tensor&,
456	                                   int64_t,
457	                                   const std::optional<std::vector<int64_t>>&,
458	                                   const std::optional<std::vector<int64_t>>&,
459	                                   const at::Tensor&,
460	                                   int64_t,
461	                                   int64_t)
462	{
463	    TORCH_CHECK(false,
464	                "all_to_all_4d_async cannot be traced: it completes through a CUDA event bound to "
465	                "torch's work registry and takes the caller's stream as an argument, neither of "
466	                "which a traced call has. Trace all_to_all_4d(out=...) instead, which moves the "
467	                "same bytes.");
468	}
469	
470	// Re-enter the DISPATCHER with the autograd keys excluded.
471	//
472	// Not a direct call to all_to_all_4d(): that would leave dispatch for good, and every key below
473	// Autograd -- Python, and through it FakeTensorMode, and Meta -- would never be consulted, so a
474	// fake tensor would reach the real kernel and die in cudaMemcpy3DAsync.
475	//
476	// The guard is what stops op.call from arriving back at the Autograd kernel. GradMode being off
477	// is not enough: it governs graph construction, not which kernel the dispatcher picks.
478	at::Tensor dispatch_below_autograd(const c10::intrusive_ptr<UlyssesGroup>&    group,
479	                                   const at::Tensor&                          input,
480	                                   int64_t                                    mode,
481	                                   const std::optional<std::vector<int64_t>>& seq_splits,
482	                                   const std::optional<std::vector<int64_t>>& head_splits)
483	{
484	    at::AutoDispatchBelowADInplaceOrView guard;
485	    static auto                          op = c10::Dispatcher::singleton()
486	                         .findSchemaOrThrow("fast_ulysses::all_to_all_4d", "")
487	                         .typed<at::Tensor(const c10::intrusive_ptr<UlyssesGroup>&,
488	                                           const at::Tensor&,
489	                                           int64_t,
490	                                           const std::optional<std::vector<int64_t>>&,
491	                                           const std::optional<std::vector<int64_t>>&)>();
492	    return op.call(group, input, mode, seq_splits, head_splits);
493	}
494	
495	// The adjoint of the collective is the collective in the other direction.
496	//
497	// mode 0 is a bijection on the global element set -- rank r's (batch, s, n, k) lands at rank
498	// owner(n) position (batch, seq_offset[r]+s, n-head_offset[p], k) -- and mode 1 with the SAME
499	// splits is `build_plan`'s scatter branch read right to left, i.e. its inverse. The Jacobian of a
500	// permutation is a permutation matrix, whose transpose is its inverse, so the vjp is `1 - mode`.
501	//
502	// The splits do NOT swap. That is worth stating because all_to_all_single's backward DOES swap its
503	// input and output split sizes: those describe one call's send and receive counts, so reversing the
504	// direction reverses their roles. seq_splits[p] / head_splits[p] are a different object -- rank p's
505	// sequence and head shard, a property of the GROUP that holds whichever way the data moves. `mode`
506	// selects which axis arrives already sharded, not what the lists mean. test_plan.py's round trip
507	// builds both plans from one pair of genuinely uneven lists and confirms it numerically.
508	//
509	// Absent splits pass through too: mode 0 with none derives seq=[x1]*ws, head=[x2/ws]*ws, and mode 1
510	// with none on that output shape derives the same pair -- and can never fail a divisibility check
511	// the forward did not already pass, since the axis it tests is ws times something.
512	class A2AFunction: public torch::autograd::Function<A2AFunction> {
513	public:
514	    static at::Tensor forward(torch::autograd::AutogradContext*          ctx,
515	                              const c10::intrusive_ptr<UlyssesGroup>&    group,
516	                              const at::Tensor&                          input,
517	                              int64_t                                    mode,
518	                              const std::optional<std::vector<int64_t>>& seq_splits,
519	                              const std::optional<std::vector<int64_t>>& head_splits)
520	    {
521	        // The graph holds the group alive. A graph that outlives destroy() raises from backward,
522	        // which is the right answer -- there is nothing left to run the collective on.
523	        ctx->saved_data["group"] = group;
524	        ctx->saved_data["mode"]  = mode;
525	        ctx->saved_data["seq"]   = seq_splits.has_value() ? c10::IValue(*seq_splits) : c10::IValue();
526	        ctx->saved_data["head"]  = head_splits.has_value() ? c10::IValue(*head_splits) : c10::IValue();
527	
528	        return dispatch_below_autograd(group, input, mode, seq_splits, head_splits);
529	    }
530	
531	    static torch::autograd::variable_list backward(torch::autograd::AutogradContext* ctx,
532	                                                   torch::autograd::variable_list    grads)
533	    {
534	        // Five entries, one per non-ctx forward argument; only `input` is differentiable.
535	        if (!grads[0].defined()) {
536	            return {at::Tensor(), at::Tensor(), at::Tensor(), at::Tensor(), at::Tensor()};
537	        }
538	        auto          group = ctx->saved_data["group"].toCustomClass<UlyssesGroup>();
539	        const int64_t mode  = ctx->saved_data["mode"].toInt();
540	
541	        std::optional<std::vector<int64_t>> seq, head;
542	        if (!ctx->saved_data["seq"].isNone()) {
543	            seq = ctx->saved_data["seq"].toIntVector();
544	        }
545	        if (!ctx->saved_data["head"].isNone()) {
546	            head = ctx->saved_data["head"].toIntVector();
547	        }
548	
549	        // The copying form, never `out` from empty_output(): that is a collective allocation, and
550	        // putting one inside backward would hand the rendezvous position to the autograd engine's
551	        // node order rather than to the caller's own program. A gradient also belongs to the
552	        // engine, which may accumulate into it or hold it, while a window is single-buffered.
553	        //
554	        // apply(), not the plain function, so grad-of-grad routes back through here.
555	        return {at::Tensor(),
556	                A2AFunction::apply(group, grads[0].contiguous(), 1 - mode, seq, head),
557	                at::Tensor(),
558	                at::Tensor(),
559	                at::Tensor()};
560	    }
561	};
562	
563	namespace {
564	
565	// The node apply() allocates is dead weight when nothing will use it, and this operator runs twice
566	// per attention layer per step.
567	at::Tensor with_reverse_ad(const c10::intrusive_ptr<UlyssesGroup>&    group,
568	                           const at::Tensor&                          input,
569	                           int64_t                                    mode,
570	                           const std::optional<std::vector<int64_t>>& seq_splits,
571	                           const std::optional<std::vector<int64_t>>& head_splits)
572	{
573	    if (!at::GradMode::is_enabled() || !input.requires_grad()) {
574	        return dispatch_below_autograd(group, input, mode, seq_splits, head_splits);
575	    }
576	    return A2AFunction::apply(group, input, mode, seq_splits, head_splits);
577	}
578	
579	// The only forward-AD level torch has.
580	constexpr uint64_t kFwLevel = 0;
581	
582	}  // namespace
583	
584	at::Tensor all_to_all_4d_autograd(const c10::intrusive_ptr<UlyssesGroup>&    group,
585	                                  const at::Tensor&                          input,
586	                                  int64_t                                    mode,
587	                                  const std::optional<std::vector<int64_t>>& seq_splits,
588	                                  const std::optional<std::vector<int64_t>>& head_splits)
589	{
590	    // Forward mode is handled HERE, not in A2AFunction: torch::autograd::Function has no jvp hook
591	    // in C++, so a dual input reaching apply() raises, and one taking with_reverse_ad's fast path
592	    // would have its tangent dropped without a word. The jvp of a permutation is the permutation, so
593	    // the tangent goes through the same call -- one more collective, which every rank issues,
594	    // because every rank runs this graph.
595	    const at::Tensor tangent = input._fw_grad(kFwLevel);
596	    if (!tangent.defined()) {
597	        return with_reverse_ad(group, input, mode, seq_splits, head_splits);
598	    }
599	    // The primal keeps the reverse-mode history and carries no tangent, so apply() may see it.
600	    at::Tensor result = with_reverse_ad(group, input._fw_primal(kFwLevel), mode, seq_splits, head_splits);
601	    result._set_fw_grad(with_reverse_ad(group, tangent, mode, seq_splits, head_splits),
602	                        kFwLevel,
603	                        /*is_inplace_op=*/false);
604	    return result;
605	}
606	
607	// A buffer shaped like this call's output, in symmetric memory, for the caller to pass back as
608	// `out`. COLLECTIVE.
609	at::Tensor empty_output(const c10::intrusive_ptr<UlyssesGroup>&    group,
610	                        const at::Tensor&                          input,
611	                        int64_t                                    mode,
612	                        const std::optional<std::vector<int64_t>>& seq_splits,
613	                        const std::optional<std::vector<int64_t>>& head_splits)
614	{
615	    require_cuda(input);
616	    const at::cuda::CUDAGuard guard(input.device());
617	    const A2APlan&            plan = group->plan(input.sizes(), mode, input.scalar_type(), seq_splits, head_splits);
618	    return group->make_output(plan.output_shape, input.scalar_type(), plan.window_numel);
619	}
620	
621	// Benchmark-only: the copying call with CUDA events between its stages, strictly ordered on one
622	// stream so they sum to the whole call. `transfer` covers the peer copies plus this rank's own
623	// share, which runs on the caller's stream underneath them and so cannot be timed apart.
624	std::tuple<at::Tensor, std::vector<double>> all_to_all_4d_timed(const c10::intrusive_ptr<UlyssesGroup>&    group,
625	                                                                const at::Tensor&                          input,
626	                                                                int64_t                                    mode,
627	                                                                const std::optional<std::vector<int64_t>>& seq_splits,
628	                                                                const std::optional<std::vector<int64_t>>& head_splits)
629	{
630	    require_cuda(input);
631	    const at::cuda::CUDAGuard guard(input.device());
632	    const Call   call = prepare(group, input, mode, seq_splits, head_splits, std::nullopt, kSyncWindow, /*lend=*/false);
633	    const int    rank = static_cast<int>(group->rank());
634	    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
635	
636	    // Default flags, not cudaEventDisableTiming: cudaEventElapsedTime below needs the timestamps.
637	    const Event marks[5];
638	    ULYSSES_CUDA_CHECK(cudaEventRecord(marks[0], stream));
639	    fast_barrier(stream, call.win->flag_ptrs, rank);
640	    ULYSSES_CUDA_CHECK(cudaEventRecord(marks[1], stream));
641	    launch_a2a_ce(call.x.data_ptr(), call.win->peer_ptrs, *call.plan, group->xfer_stream(), rank, stream);
642	    ULYSSES_CUDA_CHECK(cudaEventRecord(marks[2], stream));
643	    fast_barrier(stream, call.win->flag_ptrs, rank);
644	    ULYSSES_CUDA_CHECK(cudaEventRecord(marks[3], stream));
645	    copy_out(call, stream, rank);
646	    ULYSSES_CUDA_CHECK(cudaEventRecord(marks[4], stream));
647	
648	    ULYSSES_CUDA_CHECK(cudaEventSynchronize(marks[4]));
649	    std::vector<double> stages(4, 0.0);
650	    for (int i = 0; i < 4; ++i) {
651	        float ms = 0.0F;
652	        ULYSSES_CUDA_CHECK(cudaEventElapsedTime(&ms, marks[i], marks[i + 1]));
653	        stages[i] = static_cast<double>(ms);
654	    }
655	    return {call.output, stages};
656	}
657	
658	// Refuses, like empty_output's, rather than returning the shape with four zeros.
659	//
660	// Half of what this op returns is a measurement, and a traced call performs nothing to measure. A
661	// zeroed vector is not a missing answer, it is a wrong one: whoever reads it gets four durations
662	// with the units and the shape of real ones, and a benchmark that averages them reports a call
663	// that took no time. The shape half is available from all_to_all_4d, which is the same collective;
664	// this op exists only to time it, and timing wants the eager call.
665	std::tuple<at::Tensor, std::vector<double>> all_to_all_4d_timed_meta(const c10::intrusive_ptr<UlyssesGroup>&,
666	                                                                     const at::Tensor&,
667	                                                                     int64_t,
668	                                                                     const std::optional<std::vector<int64_t>>&,
669	                                                                     const std::optional<std::vector<int64_t>>&)
670	{
671	    TORCH_CHECK(false,
672	                "all_to_all_4d_timed cannot be traced: it returns CUDA event timings, and a traced "
673	                "call runs nothing to time. Call it eagerly, or trace all_to_all_4d instead.");
674	}
675	
676	}  // namespace ulysses
677	
678	TORCH_LIBRARY(fast_ulysses, m)
679	{
680	    m.class_<ulysses::UlyssesGroup>("UlyssesGroup")
681	        .def(torch::init<std::string, int64_t, int64_t, int64_t>())
682	        .def("destroy", &ulysses::UlyssesGroup::destroy)
683	        // TESTS ONLY, and a method rather than a pybind function because the group is a torchbind
684	        // object, which pybind cannot take. test/distributed/cudagraph.py needs it: torn data is a
685	        // SUFFICIENT signal that the handshake died, not a necessary one -- a replay where no peer
686	        // happened to be late comes back clean either way, and only the epoch says whether the
687	        // barrier was alive. Synchronising; `like` carries the dtype that keys the window.
688	        .def("epoch_debug",
689	             [](const c10::intrusive_ptr<ulysses::UlyssesGroup>& self, const at::Tensor& probe, int64_t role) {
690	                 return self->epoch(probe, static_cast<ulysses::WindowRole>(role));
691	             })
692	        // TESTS ONLY, same reason. test/distributed/correctness.py needs it: several same-shaped
693	        // async calls in flight at once is what the staging pool exists for, and the results
694	        // cannot show it -- sharing one slot is CORRECT, it only serialises the calls on the
695	        // caller's stream. The slot count separates the two. `like` carries the (shape, dtype).
696	        .def("staging_slots_debug", [](const c10::intrusive_ptr<ulysses::UlyssesGroup>& self, const at::Tensor& like) {
697	            return self->staging_slots(like);
698	        });
699	
700	    // BOTH batching keys, for every op below.
701	    //
702	    // FuncTorchBatched is the one torch.vmap uses, and it wins over an op's Autograd kernel, so it
703	    // also covers a vmap over a grad-requiring input and a nested vmap. Batched is the LEGACY
704	    // vmap's key, and it is still reachable from a supported public API: torch.autograd.grad(...,
705	    // is_grads_batched=True) -- and torch.autograd.functional.* with vectorize=True through it --
706	    // goes through torch._vmap_internals, not functorch. Registering only the first leaves that
707	    // path looping one collective per row of the batch, which is the failure being refused.
708	    //
709	    // Neither fires when the tensor handed to the collective is a closed-over constant, which is a
710	    // genuinely-once call inside somebody else's vmap and stays legal.
711	    auto refuse_batching = [&m](const char* name) {
712	        for (const c10::DispatchKey key : {c10::DispatchKey::FuncTorchBatched, c10::DispatchKey::Batched}) {
713	            m.impl(name, key, torch::CppFunction::makeFromBoxedFunction<&ulysses::refuse_vmap>());
714	        }
715	    };
716	
717	    // Functional: no alias, so it can carry an autograd formula and a meta kernel.
718	    m.def("all_to_all_4d(__torch__.torch.classes.fast_ulysses.UlyssesGroup group, Tensor input, "
719	          "int mode, int[]? seq_splits=None, int[]? head_splits=None) -> Tensor");
720	    m.impl("all_to_all_4d", c10::DispatchKey::CompositeExplicitAutograd, &ulysses::all_to_all_4d);
721	    m.impl("all_to_all_4d", c10::DispatchKey::Autograd, &ulysses::all_to_all_4d_autograd);
722	    // Explicit Meta, overriding the alias above. Deliberately NOT also torch.library.register_fake:
723	    // on 2.13 that silently replaces an existing Meta kernel, leaving two shape rules and no error
724	    // saying which one ran.
725	    m.impl("all_to_all_4d", c10::DispatchKey::Meta, &ulysses::all_to_all_4d_meta);
726	    refuse_batching("all_to_all_4d");
727	
728	    // Mutating, and says so. Not differentiable: the gradient would have to flow back out of a
729	    // buffer the caller owns and may already have overwritten.
730	    m.def("all_to_all_4d_out(__torch__.torch.classes.fast_ulysses.UlyssesGroup group, Tensor input, "
731	          "int mode, int[]? seq_splits, int[]? head_splits, Tensor(a!) out) -> ()");
732	    m.impl("all_to_all_4d_out", c10::DispatchKey::CompositeExplicitAutograd, &ulysses::all_to_all_4d_out);
733	    m.impl("all_to_all_4d_out", c10::DispatchKey::Meta, &ulysses::all_to_all_4d_out_meta);
734	    // Registered although torch's for-loop fallback already refuses out-variants: that refusal is
735	    // torch's own, for its own reasons, and a torch that grew an out= batching fallback would make
736	    // this op start looping silently. One line makes it a property of this library instead.
737	    refuse_batching("all_to_all_4d_out");
738	
739	    m.def("all_to_all_4d_staged(__torch__.torch.classes.fast_ulysses.UlyssesGroup group, "
740	          "Tensor input, int mode, int[]? seq_splits, int[]? head_splits, "
741	          "int caller_stream_id, int caller_device_index, bool lend=False) -> Tensor");
742	    m.impl("all_to_all_4d_staged", c10::DispatchKey::CompositeExplicitAutograd, &ulysses::all_to_all_4d_staged);
743	    m.impl("all_to_all_4d_staged", c10::DispatchKey::Meta, &ulysses::all_to_all_4d_staged_meta);
744	    refuse_batching("all_to_all_4d_staged");
745	
746	    m.def("all_to_all_4d_staged_out(__torch__.torch.classes.fast_ulysses.UlyssesGroup group, "
747	          "Tensor input, int mode, int[]? seq_splits, int[]? head_splits, Tensor(a!) out, "
748	          "int caller_stream_id, int caller_device_index) -> ()");
749	    m.impl("all_to_all_4d_staged_out", c10::DispatchKey::CompositeExplicitAutograd, &ulysses::all_to_all_4d_staged_out);
750	    m.impl("all_to_all_4d_staged_out", c10::DispatchKey::Meta, &ulysses::all_to_all_4d_staged_out_meta);
751	    refuse_batching("all_to_all_4d_staged_out");
752	
753	    m.def("empty_output(__torch__.torch.classes.fast_ulysses.UlyssesGroup group, Tensor input, "
754	          "int mode, int[]? seq_splits=None, int[]? head_splits=None) -> Tensor");
755	    m.impl("empty_output", c10::DispatchKey::CompositeExplicitAutograd, &ulysses::empty_output);
756	    m.impl("empty_output", c10::DispatchKey::Meta, &ulysses::empty_output_meta);
757	    // A fresh buffer has no data dependence on the tensor whose shape it was taken from, so it must
758	    // not inherit that tensor's requires_grad. Without this the Autograd key falls back to
759	    // autogradNotImplementedFallback, which builds a node over the buffer and hands back a non-leaf
760	    // the caller cannot even detach in place.
761	    m.impl("empty_output", c10::DispatchKey::Autograd, torch::CppFunction::makeFallthrough());
762	    // The loop would rendezvous once per batch element, which is the same hang with an extra way in.
763	    refuse_batching("empty_output");
764	
765	    m.def("all_to_all_4d_timed(__torch__.torch.classes.fast_ulysses.UlyssesGroup group, "
766	          "Tensor input, int mode, int[]? seq_splits=None, int[]? head_splits=None) "
767	          "-> (Tensor, float[])");
768	    m.impl("all_to_all_4d_timed", c10::DispatchKey::CompositeExplicitAutograd, &ulysses::all_to_all_4d_timed);
769	    m.impl("all_to_all_4d_timed", c10::DispatchKey::Meta, &ulysses::all_to_all_4d_timed_meta);
770	    // Same as empty_output: it measures, it does not differentiate.
771	    m.impl("all_to_all_4d_timed", c10::DispatchKey::Autograd, torch::CppFunction::makeFallthrough());
772	    refuse_batching("all_to_all_4d_timed");
773	}
774	
775	// Python `import _C` needs PyInit__C; TORCH_LIBRARY already registered at dlopen time.
776	PYBIND11_MODULE(_C, m)
777	{
778	    // The async wrapper is Python-side, so this is the one piece that has to be here: c10d::Work
779	    // is a C++ interface. Not a torch op -- it takes a raw stream handle and mutates a
780	    // process-wide registry, neither of which belongs in a schema.
781	    m.def("register_stream_completion", [](const at::Tensor& tensor, int64_t comm_stream) {
782	        return ulysses::register_stream_completion(tensor, reinterpret_cast<cudaStream_t>(comm_stream));
783	    });
784	
785	    // {(i, j): joined by NVLink} over CUDA device indices, or None when NVML cannot say.
786	    m.def("nvlink_matrix", [](const std::vector<int64_t>& devices) -> py::object {
787	        const auto matrix = ulysses::nvlink_matrix(devices);
788	        if (!matrix.has_value()) {
789	            return py::none();
790	        }
791	        py::dict out;
792	        for (const auto& entry : *matrix) {
793	            out[py::make_tuple(entry.first.first, entry.first.second)] = py::bool_(entry.second);
794	        }
795	        return out;
796	    });
797	
798	    // Empty when every pair is NVLink-joined, or when NVML cannot say.
799	    m.def("check_nvlink", &ulysses::check_nvlink);
800	
801	    // TESTS ONLY. Underscored, and not a torch op, because arming it deliberately breaks the
802	    // operator: it is the negative control for test/distributed/ce_ordering.py.
803	    m.def("_set_ce_fault", &ulysses::set_ce_fault);
804	
805	    m.def("build_info", []() {
806	        std::map<std::string, std::string> out;
807	        out["version"]        = FAST_ULYSSES_VERSION;
808	        out["cuda_arch_list"] = FAST_ULYSSES_CUDA_ARCH_LIST;
809	        return out;
810	    });
